require_once __DIR__.'/fixtures.php';
use Zinema\Identity\{Account,Principal,Password,Authentication,Recovery,SessionState,Authorization,Csrf,Upload,Audit,WindowLimiter,Factory,NativeSession};
$cases=[];
$cases['password hash verifies without plaintext storage']=function() { $p=new Password();$h=$p->hash('fictional horse galaxy 47');check($h!=='fictional horse galaxy 47' && $p->verify('fictional horse galaxy 47',$h) && !$p->verify('incorrect',$h)); };
$cases['password validation bounds and malformed types']=function() { $p=new Password();foreach (['short',[],null,str_repeat('a',129),"fictional horse\0galaxy 47"] as $v) denied(fn()=>$p->hash($v),'INVALID_INPUT');check($p->valid('no composition requirements')); };
$cases['PHP bcrypt compatibility rejects truncation and unknown formats']=function() { $p=new Password();$h=password_hash('fictional horse galaxy 47',PASSWORD_BCRYPT,['cost'=>4]);check($p->verify('fictional horse galaxy 47',$h) && $p->needsRehash($h));check(!$p->verify(str_repeat('a',73),password_hash(str_repeat('a',72),PASSWORD_BCRYPT,['cost'=>4])));check(!$p->verify('fictional horse galaxy 47','legacy-unknown')); };
$cases['registration generic duplicate response and no privilege assignment']=function() { [$s,$p,$c,$mail,$auth]=world();$r=$auth->register(' New@Example.invalid ','fictional horse galaxy 47','127.0.0.1');check($r===$auth->register('new@example.invalid','fictional horse galaxy 47','127.0.0.1') && count($s->accounts)===1);$a=$s->byEmail('new@example.invalid');check(!$a->verified && $a->permissions===['account.read','account.change']);denied(fn()=>$auth->login($a->email,'fictional horse galaxy 47','127.0.0.1'),'INVALID_CREDENTIALS'); };
$cases['registration invalid email and password rejected']=function() { [$s,$p,$c,$mail,$auth]=world();foreach (['bad',[],str_repeat('x',255).'@example.invalid'] as $e) denied(fn()=>$auth->register($e,'fictional horse galaxy 47','127.0.0.1'),'INVALID_INPUT');denied(fn()=>$auth->register('a@example.invalid','short','127.0.0.1'),'INVALID_INPUT');check(count($s->accounts)===0); };
$cases['login verified active identity returns only principal']=function() { [$s,$p,$c,$mail,$auth]=world();$a=seed($s,$p);$r=$auth->login($a->email,'fictional horse galaxy 47','127.0.0.1');check($r instanceof Principal && array_keys(get_object_vars($r))===['id','epoch'] && $s->events[0]['action']==='login'); };
$cases['unknown incorrect disabled unverified share failure']=function() { [$s,$p,$c,$mail,$auth]=world();$a=seed($s,$p);$b=seed($s,$p,str_repeat('b',32),false);$d=seed($s,$p,str_repeat('d',32),true,false);foreach ([[$a->email,'incorrect'],['absent@example.invalid','fictional horse galaxy 47'],[$b->email,'fictional horse galaxy 47'],[$d->email,'fictional horse galaxy 47']] as [$email,$pw]) denied(fn()=>$auth->login($email,$pw,'127.0.0.1'),'INVALID_CREDENTIALS'); };
$cases['successful login rehash is gradual and failed login unchanged']=function() { [$s,$p,$c,$mail,$auth]=world();$a=seed($s,$p);$old=password_hash('fictional horse galaxy 47',PASSWORD_BCRYPT,['cost'=>4]);$s->accounts[$a->id]=new Account($a->id,$a->email,$old,true,true,1,$a->permissions);denied(fn()=>$auth->login($a->email,'wrong','127.0.0.1'),'INVALID_CREDENTIALS');check($s->byId($a->id)->passwordHash===$old);$auth->login($a->email,'fictional horse galaxy 47','127.0.0.1');check($s->byId($a->id)->passwordHash!==$old); };
$cases['bounded login limiting expires without permanent account lock']=function() { [$s,$p,$c,$mail,$auth]=world(2);$a=seed($s,$p);for($i=0;$i<2;$i++) denied(fn()=>$auth->login($a->email,'wrong','127.0.0.1'),'INVALID_CREDENTIALS');denied(fn()=>$auth->login($a->email,'fictional horse galaxy 47','127.0.0.1'),'RATE_LIMITED');$c->time+=300;check($auth->login($a->email,'fictional horse galaxy 47','127.0.0.1')->id===$a->id); };
$cases['network and account dimensions both apply']=function() { [$s,$p,$c,$mail,$auth]=world(2);$a=seed($s,$p);denied(fn()=>$auth->login($a->email,'wrong','127.0.0.1'),'INVALID_CREDENTIALS');denied(fn()=>$auth->login($a->email,'wrong','127.0.0.2'),'INVALID_CREDENTIALS');denied(fn()=>$auth->login($a->email,'wrong','127.0.0.3'),'RATE_LIMITED');denied(fn()=>$auth->login('other@example.invalid','wrong','spoofed'),'INVALID_REQUEST'); };
$cases['limiter capacity and clock rollback deny']=function() { $l=new WindowLimiter(1,60,1);$l->take(str_repeat('a',64),100);denied(fn()=>$l->take(str_repeat('b',64),100),'RATE_LIMITED');denied(fn()=>$l->take(str_repeat('a',64),99),'LIMIT_UNAVAILABLE');$l->take(str_repeat('b',64),160); };
$cases['verification digest one use no auto-login']=function() { [$s,$p,$c,$mail,$auth,$recovery]=world();$a=seed($s,$p,str_repeat('a',32),false);check($recovery->request('verify',$a->email,'127.0.0.1')===['accepted'=>true]);$token=$mail->messages[0]['token'];check(!str_contains(json_encode($s->tokens),$token));check($recovery->consume('verify',$token,null,'127.0.0.1'));check($s->byId($a->id)->verified && $s->byId($a->id)->epoch===2);denied(fn()=>$recovery->consume('verify',$token,null,'127.0.0.1'),'RECOVERY_REJECTED'); };
$cases['verification expiry exact boundary and purpose binding']=function() { [$s,$p,$c,$mail,$auth,$r]=world();$a=seed($s,$p,str_repeat('a',32),false);$r->request('verify',$a->email,'127.0.0.1');$token=$mail->messages[0]['token'];denied(fn()=>$r->consume('reset',$token,'fictional replacement 58','127.0.0.1'),'RECOVERY_REJECTED');$c->time+=3600;denied(fn()=>$r->consume('verify',$token,null,'127.0.0.1'),'RECOVERY_REJECTED');check(!$s->byId($a->id)->verified); };
$cases['resend replaces older token and throttles']=function() { [$s,$p,$c,$mail,$auth,$r]=world(2);$a=seed($s,$p,str_repeat('a',32),false);$r->request('verify',$a->email,'127.0.0.1');$old=$mail->messages[0]['token'];$r->request('verify',$a->email,'127.0.0.1');denied(fn()=>$r->consume('verify',$old,null,'127.0.0.1'),'RECOVERY_REJECTED');denied(fn()=>$r->request('verify',$a->email,'127.0.0.1'),'RATE_LIMITED'); };
$cases['recovery unknown and mail failure do not disclose account']=function() { [$s,$p,$c,$mail,$auth,$r]=world();$a=seed($s,$p);$unknown=$r->request('reset','unknown@example.invalid','127.0.0.1');check(count($mail->messages)===0);$mail->fail=true;check($unknown===$r->request('reset',$a->email,'127.0.0.1')); };
$cases['reset changes only subject hash revokes concurrent sessions and preserves admin permission MFA gate']=function() { [$s,$p,$c,$mail,$auth,$r]=world();$a=seed($s,$p,str_repeat('a',32),true,true,['account.read','admin.enter']);$b=seed($s,$p,str_repeat('b',32));$states=[SessionState::establish(new Principal($a->id,1),$c->time),SessionState::establish(new Principal($a->id,1),$c->time)];$r->request('reset',$a->email,'127.0.0.1');$t=$mail->messages[0]['token'];$r->consume('reset',$t,'fictional replacement 58','127.0.0.1');foreach ($states as &$state) check(SessionState::resolve($state,$s,$c->time)===null);check($p->verify('fictional replacement 58',$s->byId($a->id)->passwordHash));check($p->verify('fictional horse galaxy 47',$s->byId($b->id)->passwordHash));denied(fn()=>(new Authorization($s))->require(new Principal($a->id,2),'admin.enter',null,'fixture',$c->time),'STEP_UP_REQUIRED');denied(fn()=>$r->consume('reset',$t,'fictional replacement 59','127.0.0.1'),'RECOVERY_REJECTED'); };
$cases['reset malformed and expired tokens rejected']=function() { [$s,$p,$c,$mail,$auth,$r]=world();$a=seed($s,$p);foreach ([[],null,'bad',str_repeat('a',64)] as $t) denied(fn()=>$r->consume('reset',$t,'fictional replacement 58','127.0.0.1'),'RECOVERY_REJECTED');$r->request('reset',$a->email,'127.0.0.1');$t=$mail->messages[0]['token'];$c->time+=1800;denied(fn()=>$r->consume('reset',$t,'fictional replacement 58','127.0.0.1'),'RECOVERY_REJECTED');check($p->verify('fictional horse galaxy 47',$s->byId($a->id)->passwordHash)); };
$cases['reset replacement failure rolls token and account back']=function() { [$s,$p,$c,$mail,$auth,$r]=world();$a=seed($s,$p);$r->request('reset',$a->email,'127.0.0.1');$token=$mail->messages[0]['token'];$before=$s->tokens;$s->failReplace=true;denied(fn()=>$r->consume('reset',$token,'fictional replacement 58','127.0.0.1'),'STORAGE_UNAVAILABLE');check($s->tokens===$before && $s->byId($a->id)->epoch===1);$s->failReplace=false;check($r->consume('reset',$token,'fictional replacement 58','127.0.0.1')); };
$cases['required audit failure rolls reset and registration back']=function() { [$s,$p,$c,$mail,$auth,$r]=world();$a=seed($s,$p);$r->request('reset',$a->email,'127.0.0.1');$t=$mail->messages[0]['token'];$before=$s->tokens;$s->failAudit=true;denied(fn()=>$r->consume('reset',$t,'fictional replacement 58','127.0.0.1'),'AUDIT_UNAVAILABLE');check($s->tokens===$before && $s->byId($a->id)->epoch===1);denied(fn()=>$auth->register('another@example.invalid','fictional horse galaxy 47','127.0.0.1'),'AUDIT_UNAVAILABLE');check(count($s->accounts)===1); };
$cases['audit failure cannot authorize login']=function() { [$s,$p,$c,$mail,$auth]=world();$a=seed($s,$p);$s->failAudit=true;denied(fn()=>$auth->login($a->email,'fictional horse galaxy 47','127.0.0.1'),'AUDIT_UNAVAILABLE'); };
$cases['password change requires current credential and revokes sessions']=function() { [$s,$p,$c,$mail,$auth]=world();$a=seed($s,$p);$principal=new Principal($a->id,1);$state=SessionState::establish($principal,$c->time);denied(fn()=>$auth->change($principal,'wrong','fictional replacement 58','127.0.0.1'),'INVALID_CREDENTIALS');$auth->change($principal,'fictional horse galaxy 47','fictional replacement 58','127.0.0.1');check(SessionState::resolve($state,$s,$c->time)===null); };
$cases['session expiry absolute idle clock reversal and disabled status']=function() { [$s,$p,$c]=world();$a=seed($s,$p);$base=SessionState::establish(new Principal($a->id,1),$c->time);foreach ([1800,-1] as $delta) { $v=$base;check(SessionState::resolve($v,$s,$c->time+$delta)===null); }$v=$base;$v['seen']+=28799;check(SessionState::resolve($v,$s,$c->time+28800)===null);$v=$base;check(SessionState::resolve($v,$s,$c->time+1)->id===$a->id);$s->accounts[$a->id]=new Account($a->id,$a->email,$a->passwordHash,false,true,1,$a->permissions);check(SessionState::resolve($v,$s,$c->time+2)===null); };
$cases['session malformed and legacy flags never adopted']=function() { [$s,$p,$c]=world();seed($s,$p);foreach ([[],['admin_id'=>1,'user_id'=>1,'mfa'=>true],['subject'=>[],'epoch'=>1,'created'=>1,'seen'=>1,'binding'=>str_repeat('a',64)]] as $v) check(SessionState::resolve($v,$s,$c->time)===null); };
$cases['RBAC denies cross-user unknown permission and self promotion']=function() { [$s,$p,$c]=world();$a=seed($s,$p);$auth=new Authorization($s);$principal=new Principal($a->id,1);check($auth->require($principal,'account.read',$a->id,'fixture',$c->time)->id===$a->id);foreach (['admin.enter','admin.users','owner','*'] as $perm) denied(fn()=>$auth->require($principal,$perm,$a->id,'fixture',$c->time),'ACCESS_DENIED');denied(fn()=>$auth->require($principal,'account.read',str_repeat('b',32),'fixture',$c->time),'ACCESS_DENIED'); };
