$cases['CSRF HTML and AJAX tokens types expiry origin method']=function() { $s=[];$t=Csrf::token($s,100);check(Csrf::token($s,101)===$t && Csrf::valid($s,$t,101));Csrf::mutation('POST','https://example.invalid','https://example.invalid',$s,$t,101);foreach ([null,[],str_repeat('b',64)] as $bad) check(!Csrf::valid($s,$bad,101));check(!Csrf::valid($s,$t,99) && !Csrf::valid($s,$t,3700));denied(fn()=>Csrf::mutation('POST','https://forged.invalid','https://example.invalid',$s,$t,101),'CSRF_REJECTED');denied(fn()=>Csrf::mutation('GET','https://example.invalid','https://example.invalid',$s,$t,101),'METHOD_NOT_ALLOWED'); };
$cases['legacy CSRF malformed array and future timestamp regression']=function() { require_once __DIR__.'/../../Zinema.lk Website/includes/csrf_helper.php';session_start();$_SESSION=['csrf_token'=>str_repeat('a',64),'csrf_token_time'=>time()];check(validate_csrf_token(str_repeat('a',64)));check(!validate_csrf_token([]) && !validate_csrf_token(null));$_SESSION['csrf_token_time']=time()+20;check(!validate_csrf_token(str_repeat('a',64)));session_destroy(); };
