$cases['audit event shape excludes secrets and arbitrary context']=function() { [$s,$p,$c,$mail,$auth,$r,$audit]=world();$a=seed($s,$p);foreach (['role.change','content.publish','access.denied','upload'] as $action) $s->transaction(fn()=>$audit->record($action,'denied',$a->id,$a->id));foreach ($s->events as $event) check(array_keys($event)===['id','at','actor','action','target','result']);denied(fn()=>$s->transaction(fn()=>$audit->record('password=private','allowed')),'AUDIT_UNAVAILABLE');denied(fn()=>$s->transaction(fn()=>$audit->record('login','allowed','email@example.invalid')),'AUDIT_UNAVAILABLE'); };
$cases['HTTPS session parameters and insecure non-loopback refusal']=function() { $dir=ini_get('session.save_path');denied(fn()=>NativeSession::start('http://127.0.0.1','production','127.0.0.1',false,$dir),'SESSION_UNAVAILABLE');denied(fn()=>NativeSession::start('http://127.0.0.1','test','192.0.2.1',false,$dir),'SESSION_UNAVAILABLE');denied(fn()=>NativeSession::start('https://example.invalid','production','127.0.0.1',false,$dir),'SESSION_UNAVAILABLE');NativeSession::start('https://example.invalid','production','127.0.0.1',true,$dir);$p=session_get_cookie_params();check($p['secure'] && $p['httponly'] && $p['samesite']==='Lax' && $p['lifetime']===0 && ini_get('session.use_strict_mode')==='1');NativeSession::logout(); };
$cases['disabled account cannot consume a previously issued reset token']=function() { [$s,$p,$c,$mail,$auth,$r]=world();$a=seed($s,$p);$r->request('reset',$a->email,'127.0.0.1');$token=$mail->messages[0]['token'];$s->accounts[$a->id]=new Account($a->id,$a->email,$a->passwordHash,false,true,1,$a->permissions);denied(fn()=>$r->consume('reset',$token,'fictional replacement 58','127.0.0.1'),'RECOVERY_REJECTED');check($s->byId($a->id)->epoch===1 && $s->byId($a->id)->passwordHash===$a->passwordHash); };
$name=$argv[1]??'';
if ($name==='list') { echo json_encode(array_keys($cases),JSON_THROW_ON_ERROR);exit; }
if (!isset($cases[$name])) exit(2);
try { $cases[$name]();echo json_encode(['passed'=>true],JSON_THROW_ON_ERROR); }
catch (Throwable $e) { fwrite(STDERR,json_encode(['failure'=>'SYNTHETIC_CONTRACT_FAILED','kind'=>get_class($e),'line'=>$e->getLine()],JSON_THROW_ON_ERROR));exit(1); }
